def check_brackets(str_: str) -> bool:
    """
    >>> check_brackets('()[]{}')
    True
    >>> check_brackets('](')
    False
    >>> check_brackets('(]')
    False
    >>> check_brackets('([)]')
    False
    >>> check_brackets('{[]}')
    True
    """
    stack = []
    pairs = {'(': ')', '[': ']', '{': '}'}

    for char in str_:
        if char in pairs:
            stack.append(char)
        elif stack and char == pairs[stack[-1]]:
            stack.pop()
        else:
            return False
    return not stack


