    True
    >>> deep_compare([1, 2, 3], [1, 2, 3])
    True
    >>> deep_compare([1, 2, 3], [1, 2, '3'])
    False
    """
    if type(x) != type(y):
        return False
    elif isinstance(x, list):
        if len(x) != len(y):
            return False
