def to_integer(number: float) -> int:
    """ If the given number is rounded to the nearest integer, it should return
    the integer. Otherwise, it should return the nearest integer to the given
    number.
    >>> to_integer(3.5)
    4
    >>> to_integer(2.1)
    2
    """
    if is_number_rounded(number):
        return int(number)
    else:
        return round(number)

