def is_prime(n: int) -> bool:
    """ Check whether a number is a prime number.
    >>> is_prime(0)
    False
    """
    if n <= 1:
        return False
    for i in range(2, n):
        if n % i == 0:
            return False
    return True

def next_prime(n: int) -> int:
    """ Find the smallest prime number greater than the given one.
    >>> next_prime(6)
    7
    """
    n = n + 1
    while not is_prime(n):
        n += 1
    return n

